const caseRow = $input.first().json;
const trigger = $('RA Launcher Trigger').first().json;

function parseList(value) {
  if (!value) return [];
  if (Array.isArray(value)) return value;
  const text = String(value).trim();
  if (!text) return [];
  try {
    const parsed = JSON.parse(text);
    return Array.isArray(parsed) ? parsed : [];
  } catch (e) {
    return text.split(',').map(v => v.trim()).filter(Boolean);
  }
}

const applicantType = caseRow.applicant_type;
let required = [];
if (applicantType === 'Individual') {
  required = ['RA-01', 'RA-06'];
} else if (applicantType === 'Corporate') {
  required = ['RA-02', 'RA-06'];
} else if (applicantType === 'Fund') {
  required = ['RA-02', 'RA-03', 'RA-04', 'RA-06'];
}

const includeInfra = [true, 'true', 'yes', '1', 1].includes(trigger.include_infrastructure_research);
if (includeInfra && !required.includes('RA-05')) required.push('RA-05');

const override = parseList(trigger.ra_codes_json || trigger.ra_codes);
const raCodes = override.length ? override : required;
if (!raCodes.length) {
  throw new Error(`No RA codes resolved for case ${caseRow.case_id} (${applicantType})`);
}

const skillMap = {
  'RA-00': '003 Research Agents/RA-00 Preliminary Background Screen/SKILL.md',
  'RA-01': '003 Research Agents/RA-01 Individual Background Research/SKILL.md',
  'RA-02': '003 Research Agents/RA-02 Company Research/SKILL.md',
  'RA-03': '003 Research Agents/RA-03 Fund Asset Class & Market Research/SKILL.md',
  'RA-04': '003 Research Agents/RA-04 Legal Counsel Quality Assessment/SKILL.md',
  'RA-05': '003 Research Agents/RA-05 Infrastructure & Exchange Research/SKILL.md',
  'RA-06': '003 Research Agents/RA-06 Background Checks/SKILL.md'
};
const signalMap = {
  'RA-01': 'ra01_ready', 'RA-02': 'ra02_ready', 'RA-03': 'ra03_ready',
  'RA-04': 'ra04_ready', 'RA-05': 'ra05_ready', 'RA-06': 'ra06_ready'
};

const outputBase = trigger.output_base_path || `client/${caseRow.applicant_id}/outputs/03_Research_Agents`;
const envRunnerUrl = (typeof $env !== 'undefined' && $env.CAR_RA_RUNNER_URL) ? $env.CAR_RA_RUNNER_URL : '';
const runnerUrl = String(trigger.runner_url || envRunnerUrl || '').trim();
const launchedBy = trigger.launched_by || 'CAR Trigger MCP';
const forceRelaunch = [true, 'true', 'yes', '1', 1].includes(trigger.force_relaunch);

return raCodes.map(code => {
  const raCode = String(code).toUpperCase().replace('_', '-');
  if (!skillMap[raCode]) throw new Error(`Unsupported RA code: ${code}`);
  return {
    json: {
      case_id: caseRow.case_id,
      applicant_id: caseRow.applicant_id,
      applicant_type: applicantType,
      applicant_name: caseRow.primary_contact_name,
      applicant_email: caseRow.primary_contact_email,
      licence_target: caseRow.licence_target,
      folder_root_id: caseRow.folder_root_id,
      folder_url: caseRow.folder_url,
      intake_data: caseRow.intake_data,
      received_documents: caseRow.received_documents || [],
      agent: raCode,
      signal_type: signalMap[raCode] || null,
      skill_path: skillMap[raCode],
      output_base_path: outputBase,
      output_md_path: `${outputBase}/${raCode.toLowerCase()}_${caseRow.applicant_id}.md`,
      output_json_path: `${outputBase}/machine_json/${raCode.toLowerCase()}_${caseRow.applicant_id}.json`,
      runner_url: runnerUrl,
      runner_configured: !!runnerUrl,
      force_relaunch: forceRelaunch,
      launched_by: launchedBy,
      launch_notes: trigger.notes || null
    }
  };
});
